// Deliberately separate from the original bank. Run manually to regenerate new banks.
import {readFile,writeFile} from 'node:fs/promises';
const original=JSON.parse(await readFile('public/questions.json','utf8'));
const source=id=>structuredClone(original.find(q=>q.id===id).source);
const extra=[];
function add(base,topic,en,zh,options,whyEn,whyZh,diagram){
  const id=extra.length+1,answer=(id-1)%4;
  const pairs=options.map(([en,zh])=>({en,zh}));
  const correct=pairs.shift();pairs.splice(answer,0,correct);
  extra.push({id,topic,difficulty:'applied',en,zh,options:pairs,answer,explanation:{en:whyEn,zh:whyZh},source:source(base),...(diagram?{diagram:{type:'confusion',...diagram}}:{})});
}
add(1,'foundations','A factory model assigns every item either "defective" or "acceptable". The company inspects thousands of items. What determines the task type?','工廠模型把每件產品分成「瑕疵」或「合格」，每天檢查數千件。應依什麼判定任務類型？',[
['Two possible output classes make it binary classification','輸出只有兩類，因此是二元分類'],['Thousands of samples make it multiclass classification','樣本數千筆，因此是多類別分類'],['The numeric sample count makes it regression','樣本數是數字，因此是回歸'],['The factory setting makes it sequence generation','在工廠使用，因此是序列生成']],
'The number of target classes determines classification type, not the number of examples. There are two possible labels. Regression predicts a numeric quantity; sequence generation produces a sequence, neither of which is the requested output.','分類類型看的是目標有幾種可能類別，不是有多少樣本。此處輸出兩種標籤，因此為二元分類；回歸預測數值量，序列生成輸出序列，都不是本題要求。');
add(2,'foundations','A message is assigned exactly one department: finance, IT, HR, or facilities. Which design fits the target?','每則訊息只能分配到財務、資訊、人資、總務其中一個部門，哪種任務設計符合？',[
['Single-label multiclass classification','單標籤多類別分類'],['Four separate continuous regression targets','四個獨立連續回歸目標'],['Binary classification because each decision has an answer','每次決定都有答案，所以是二元分類'],['Sequence-to-sequence translation','序列到序列翻譯']],
'Exactly one of four categories is selected. The department names are not continuous values, and having one answer does not mean there are only two possible classes. No translated text sequence is required.','每筆只選四個部門之一，屬單標籤多類別分類。部門名稱不是連續數值；每題只有一個答案，也不代表只有兩種類別。題目亦未要求輸出翻譯文字。');
add(3,'foundations','A model estimates a parcel\'s delivery time in minutes, allowing values such as 42.7. Which target description is correct?','模型估計包裹送達時間，以分鐘表示，可輸出 42.7 等數值。何者正確？',[
['A numeric amount is predicted, so it is regression','預測數值量，因此是回歸'],['Minutes are labels, so it must be multiclass classification','分鐘是標籤，所以必定為多類別分類'],['It is binary classification because delivery eventually happens','最後會送達，所以是二元分類'],['It is text generation because a number can be printed','數字可以印成文字，所以是文字生成']],
'The target is a measurable amount rather than one predefined category. Printing that amount as characters does not change the learning task. Delivery yes/no and early/on-time/late would be different targets from minutes.','目標是可量測的數值量，不是預先定義的類別。把數字印成字串不會改變任務性質；是否送達、提早／準時／延遲，則是和預測分鐘不同的目標。');
add(3,'foundations','The same delivery data is relabeled as "early", "on time", or "late" instead of minutes. What changes?','同一批送貨資料不再預測分鐘，改標為「提早」「準時」「延遲」。任務如何改變？',[
['The target changes from regression to multiclass classification','目標從回歸改為多類別分類'],['The target remains regression because the input data is unchanged','輸入資料相同，所以仍是回歸'],['It becomes binary classification because the data has inputs and outputs','資料有輸入與輸出，所以變成二元分類'],['It becomes unsupervised because labels have names','標籤是名稱，所以變成非監督式']],
'Task type depends on what is predicted. Replacing a duration with one of three categories changes the target to multiclass classification, even with identical inputs. Inputs versus outputs are not the two classes, and explicit labels do not make a task unsupervised.','任務類型取決於要預測什麼。即使輸入不變，把時間量換成三種類別之一，就改為多類別分類；輸入與輸出不是「兩種類別」，有明確標籤也不會因改用文字而成為非監督式。');
add(2,'foundations','A classifier assigns one quality grade coded 0, 1, or 2. The codes are category names, not measured quantities. Which interpretation is appropriate?','分類器輸出品質等級代碼 0、1、2；這些只是類別名稱，不是量測數值。應如何解讀？',[
['Three-category classification; numeric encoding does not turn classes into quantities','三類分類，數值編碼不會讓類別變成數值量'],['Regression whenever an output contains digits','只要輸出有數字就是回歸'],['Binary classification because the codes start at zero','代碼從零開始，所以是二元分類'],['A tensor-transformation task with no labels','沒有標籤的張量轉換任務']],
'The target meaning matters. The three integers encode three discrete grades. Their written numeric form does not establish a continuous prediction task; starting from zero says nothing about class count, and grades are still labels.','應看目標的意義。三個整數表示三種離散等級，不會因以數字書寫就變成連續數值預測；是否從零編號與類別數無關，品質等級也仍是標籤。');
add(1,'foundations','A spam detector reports a probability of spam and then chooses spam or not spam. What is the underlying prediction task?','垃圾郵件偵測器先給垃圾郵件的機率，再判為垃圾或非垃圾。底層預測任務是什麼？',[
['Binary classification, because the target has two classes','二元分類，因為目標只有兩類'],['Regression solely because probabilities are numeric','只因機率是數字，所以是回歸'],['Multiclass classification because many probability values are possible','機率有很多可能值，所以是多類別分類'],['Translation from one language to another','語言間的翻譯']],
'The target label is spam versus not spam. A classifier may output a score or probability to support that decision; the score is not an additional set of target classes. No continuous measured target or translated sequence was specified.','目標標籤是垃圾與非垃圾。分類器可提供分數或機率輔助判斷，這些分數不是新的目標類別；本題沒有要估計連續量測值，也沒有要求翻譯序列。');
add(3,'foundations','Which pair contains a classification target followed by a regression target?','哪組依序為「分類目標」和「回歸目標」？',[
['A product\'s category; its expected selling price','商品類別；預期售價'],['A product\'s weight; its expected selling price','商品重量；預期售價'],['A product\'s category; its shipping category','商品類別；運送類別'],['A product\'s expected selling price; its category','預期售價；商品類別']],
'Category membership is discrete, while price is a numeric quantity. Weight and price are both numeric targets; two categories are both classification targets. Reversing price and category reverses the requested order.','商品類別是離散標籤，價格是數值量。重量與價格都是數值目標；兩種分類名稱都是分類目標；若先價格再類別，則把題目要求的順序顛倒。');
add(2,'foundations','A sentiment system previously chose positive or negative. Neutral is added as a third possible label, and each review still gets exactly one label. What changes?','情緒系統原本只選正面或負面，現在新增中立，每則評論仍只得一個標籤。何者改變？',[
['It changes from binary to single-label multiclass classification','從二元分類改為單標籤多類別分類'],['It changes from classification to regression','從分類改為回歸'],['It becomes a task that must assign all three labels to every review','每則評論必須同時取得全部三個標籤'],['It stops needing a target label','不再需要目標標籤']],
'The possible labels increase from two to three, but each example still has one categorical target. It is not a continuous amount, and adding a possible class does not require assigning every class to every example.','可選標籤從兩種增加為三種，但每筆仍只有一個類別目標。它不是連續數值；增加一種可選類別，也不表示每筆都必須同時取得所有標籤。');
add(10,'foundations','To predict whether a subscriber renews, you have usage hours, subscription age and a renewed yes/no column. Which belongs in y?','要預測訂戶是否續訂，資料含使用時數、訂閱時間及是否續訂欄位。哪個應作為 y？',[
['The renewed yes/no column','是否續訂欄位'],['All three columns together as input features','三個欄位全部作為輸入特徵'],['Only the number of rows','只有資料列數'],['The storage filename','儲存檔名']],
'The label y is the outcome the model is asked to predict: renewal. The observed usage and subscription information can form X. Treating the outcome as an input confuses predictors with the target; row count and filename are not the requested labels.','y 是模型被要求預測的結果，此處為是否續訂；使用時數和訂閱時間可作為 X。把結果也放入輸入，會混淆特徵與目標；列數與檔名不是所需的標籤。');
add(5,'foundations','A help desk wants one of five issue categories, but a proposed model writes a free-form reply. What should be checked first?','客服需求是輸出五種問題類別之一，但提案模型卻撰寫自由文字回覆。首先應檢查什麼？',[
['Whether the model\'s output matches the required classification target','模型輸出是否符合所需的分類目標'],['Whether the reply contains enough decimal places','回覆是否有足夠小數位數'],['Whether five categories imply five training samples','五種類別是否代表五筆訓練資料'],['Whether any written output is automatically correct','文字輸出是否自動等於正確答案']],
'A generated response and a categorical routing label solve different output tasks. First align the target with the requirement. Decimal places and training sample count do not fix that mismatch, and readable text does not prove that the intended label was produced.','生成回覆與輸出派工類別是不同的輸出任務，應先讓目標符合需求。小數位數或樣本數不能解決目標不符；文字通順也不能證明產生了所需類別。');

add(21,'models','Two linear separators classify every training point correctly. Under the simplified hard-margin SVM idea, which separator is preferred?','兩條線性分隔邊界都正確分類所有訓練點，依簡化硬間隔 SVM 的想法，較偏好哪條？',[
['The one with the wider minimum gap to the nearest class points','距離最近類別點的最小間隔較寬者'],['The one passing closest to any training point','最靠近任一訓練點者'],['The one drawn with the thickest pen','畫線最粗者'],['Either one solely because training accuracy ties','只因訓練正確率相同就完全無差別']],
'For separable data, the maximum-margin idea distinguishes separators even when both have perfect training accuracy. The nearest points constrain the margin. Line thickness is visual styling, and deliberately crowding a point reduces rather than widens the margin.','在線性可分範例中，即使訓練正確率相同，最大間隔仍能區分兩條邊界；最近的點會限制間隔。圖上的線寬不是模型性質，刻意貼近某個點反而縮小間隔。');
add(22,'models','In a clean, linearly separable SVM example, which points are most directly involved in setting the margin?','在乾淨且線性可分的 SVM 範例，哪些點最直接決定間隔？',[
['The support vectors near the separating margins','接近分隔間隔的支援向量'],['Only the most distant points from the boundary','只有離邊界最遠的點'],['Only the average of the row numbers','只有資料列編號的平均'],['Any points chosen by alphabetical filename order','依檔名字母序任選的點']],
'The support vectors constrain the separating margin in the simplified separable case. Points far inside a class are not automatically the limiting points. Row numbers and filenames are bookkeeping, not geometric evidence for a margin.','在簡化線性可分情況，支援向量會限制分隔間隔；深入類別內部、離邊界很遠的點，不會因此自動成為限制點。列號和檔名是管理資訊，不是幾何間隔的依據。');
add(23,'models','A straight boundary cannot separate a circular cluster from a surrounding ring. What is the conceptual reason to consider a nonlinear kernel?','一群圓形內部資料與外圍環狀資料無法用直線分開，考慮非線性 kernel 的概念理由是什麼？',[
['To allow a richer feature-space comparison and a nonlinear boundary in the original space','讓特徵空間的比較更有彈性，在原空間形成非線性邊界'],['To delete all labels before supervised training','在監督式訓練前刪掉所有標籤'],['To guarantee perfect performance on unseen data','保證對未見資料全部預測正確'],['To turn every classification problem into a time prediction','把所有分類都轉成時間預測']],
'A suitable kernel lets SVM represent relationships beyond an original-space straight line. It does not remove the need for class labels, guarantee generalization, or change the application target into regression. Suitability still has to be evaluated.','適當的 kernel 能讓 SVM 表達超越原空間直線的關係，但不會取消類別標籤、保證泛化表現，或把應用目標改成回歸，仍須以資料評估是否適合。');
add(24,'models','A dataset is well separated by a straight boundary. Does SVM necessarily require a complicated nonlinear kernel?','若資料已能以直線良好分隔，SVM 是否必須使用複雜的非線性 kernel？',[
['No; a linear model can be a reasonable candidate','不必，線性模型可以是合理候選'],['Yes; SVM can never use a linear kernel','必須，SVM 絕不能用線性 kernel'],['Yes; kernel complexity always guarantees better test performance','必須，kernel 越複雜測試表現一定越好'],['No; this proves labels are unnecessary','不必，這代表不需要標籤']],
'Linear kernels are valid SVM choices, and more complexity does not guarantee better predictions. A simple candidate should still be evaluated. This choice does not change supervised classification into learning without labels.','線性 kernel 是有效的 SVM 選項，更複雜不保證預測較好；簡單候選仍應經過評估。是否需要非線性關係，不會改變監督式分類需要標籤的事實。');
add(21,'models','A proposed SVM boundary cuts through many labeled points. Which observation directly challenges the claim that this is a good separating boundary?','某條提議的 SVM 邊界把許多有標籤的點分錯，哪項觀察最直接反駁它是好邊界的說法？',[
['Its predicted sides disagree with many known class labels','它把許多點分到與已知類別不符的一側'],['Its display color is not green','顯示顏色不是綠色'],['Its chart has an English title','圖表標題是英文'],['Its dataset filename is short','資料檔名很短']],
'A separating classifier is judged by how its decision relates to class labels and by suitable evaluation, not plot styling. A complicated-looking line is not evidence of success when many labeled examples are assigned to the wrong side.','分隔分類器應看決策與類別標籤是否相符，並用合適方式評估，而不是看圖的配色、標題或檔名。邊界看來複雜，並不能抵消大量已知樣本被分錯的問題。');
add(22,'models','In a simplified separable example, several distant non-support points move slightly without changing the support vectors. Which statement is most defensible?','簡化可分範例中，數個遠離邊界的非支援點稍微移動，支援向量並未改變。哪句最合理？',[
['The separating boundary need not change if the margin constraints stay the same','若間隔限制相同，分隔邊界不一定改變'],['Every moved point must become a support vector','所有移動的點必定變成支援向量'],['The class labels necessarily disappear','類別標籤必定消失'],['The learning rate must become zero','學習率必須歸零']],
'The key condition is that the limiting support-vector constraints remain unchanged. Moving a distant point does not by itself force a new separator. It neither deletes labels nor dictates a learning rate, and movement alone does not define a support vector.','關鍵條件是限制間隔的支援向量約束未變。遠方的點稍微移動，不一定迫使邊界改變；這也不會刪除標籤、決定學習率，移動本身更不是支援向量的定義。');
add(23,'models','In an SVM workflow, which change concerns the representation of relationships between samples rather than changing the desired labels?','在 SVM 流程中，哪種改變是調整樣本間關係的表示，而不是更改預測目標標籤？',[
['Choosing an appropriate kernel','選擇適當的 kernel'],['Changing spam/not-spam into delivery minutes','把垃圾／非垃圾改成送達分鐘'],['Replacing all known labels with random labels','把已知標籤全部換成隨機標籤'],['Using the filename as the answer key','把檔名當成標準答案']],
'Kernel choice changes how similarity or inner products are represented for the SVM decision. Replacing the target with a duration changes the task itself. Randomizing labels destroys the intended training signal, while a filename is not a principled decision rule.','Kernel 的選擇改變 SVM 如何表達相似關係或內積；改成預測時間則是改變任務目標。隨機改標籤會破壞訓練訊號，使用檔名也不是合理決策依據。');
add(24,'models','A classmate claims that using the same kernel on two datasets guarantees equally good performance. What is the main problem with that claim?','同學說兩個資料集使用相同 kernel，就保證表現一樣好。主要問題是什麼？',[
['Kernel suitability depends on the data and must be evaluated','Kernel 是否合適取決於資料，仍須評估'],['All kernels are actually identical','所有 kernel 其實完全相同'],['A kernel determines the true labels for every dataset','Kernel 會決定每個資料集的真實標籤'],['Evaluation is irrelevant to SVM','SVM 不需要評估']],
'A kernel is a modeling choice, not a universal certificate of quality. Different distributions and relationships can favor different models. Kernels are not all identical, do not create ground-truth labels, and do not eliminate evaluation.','Kernel 是建模選擇，不是品質保證。不同資料分布與關係可能需要不同模型；kernel 並非全部相同、不會產生真實標籤，也不會讓評估失去必要性。');
add(21,'models','A model separates examples in a feature space. What does the decision boundary represent?','模型在特徵空間分開樣本，決策邊界代表什麼？',[
['Where the model\'s assigned class changes between regions','模型分配的類別在不同區域間改變的位置'],['The order in which files were downloaded','檔案下載順序'],['The list of missing-value counts','各欄位缺失值數量清單'],['A promise that all future predictions are correct','所有未來預測皆正確的保證']],
'The boundary separates regions assigned different labels by the classifier. It is a model decision, not a statement of infallibility. Download order and missing-value counts are different aspects of data handling, not the geometric decision boundary.','決策邊界分隔分類器會給不同標籤的區域，是模型的判斷規則，不是永不出錯的保證。下載順序、缺值數量屬資料處理資訊，並不是幾何分類邊界。');
add(21,'models','Before fitting a supervised SVM classifier, which pair of information is needed?','在訓練監督式 SVM 分類器前，需要哪組資訊？',[
['Feature representations and corresponding training class labels','特徵表示及對應的訓練類別標籤'],['Only the final exam\'s room number','只有考試教室號碼'],['Only randomly chosen predicted labels with no inputs','只有無輸入依據的隨機預測標籤'],['Only a screenshot of a boundary, with no sample data','只有一張邊界截圖，沒有樣本資料']],
'A supervised classifier learns a relationship between X and known training labels y. A room number, unsupported random predictions, or a picture without underlying samples cannot supply that relationship. The kernel does not replace the training data.','監督式分類器學的是 X 與已知訓練標籤 y 的關係。教室號碼、沒有依據的隨機預測、缺乏底層樣本的截圖，都不能提供這種關係；kernel 也不能取代訓練資料。');

add(25,'models','Training loss repeatedly jumps up after large parameter updates. A recent change greatly increased the learning rate. What is a reasonable first hypothesis?','大幅提高學習率後，訓練損失在大型參數更新後反覆跳高，合理的初步假設是什麼？',[
['The updates may be overshooting a low-loss region','更新可能跨過較低損失區域'],['The class names must have changed automatically','類別名稱必定自動改變'],['A larger learning rate guarantees a lower loss at every step','學習率更大保證每一步損失更低'],['The number of input features must now be zero','輸入特徵數必定變為零']],
'A too-large step can overshoot and cause oscillation or divergence, consistent with the observed change. This is a hypothesis to test, not proof that learning rate is the sole possible cause. It does not rename classes or remove features; larger steps do not guarantee lower loss.','過大的步幅可能越過低點，引起震盪或發散，與描述的變化相符；這是待檢驗的假設，不是證明只有學習率會造成此現象。學習率不會改類別名稱或刪特徵，更不保證每一步損失降低。');
add(26,'models','A model\'s loss decreases steadily but extremely slowly with a tiny learning rate. Which trade-off does this illustrate?','模型在很小的學習率下，損失穩定但極慢地降低，這顯示什麼取捨？',[
['Small updates can be stable but need many steps','小幅更新可能穩定，但需要更多步驟'],['Tiny learning rates always make training finish immediately','學習率極小一定立刻訓練完'],['Learning rate controls the number of output classes','學習率控制輸出類別數'],['A small learning rate removes the need for training data','學習率小就不需要訓練資料']],
'Learning rate scales update size. Very small steps can slow convergence even when the direction is useful. It does not set class count, replace data, or guarantee immediate training completion; neither arbitrarily small nor arbitrarily large is universally best.','學習率縮放更新步幅，即使方向有幫助，步幅太小仍可能使收斂很慢。它不決定類別數、不取代資料，也不保證立刻完成；極小或極大都不是通用最佳選擇。');
add(26,'models','You set a learning rate before training; training then updates the model weights. Which distinction is correct?','你在訓練前設定學習率，訓練時再更新模型權重。哪個區分正確？',[
['Learning rate controls training updates; weights are learned model parameters','學習率控制訓練更新，權重是模型學習的參數'],['Learning rate is the observed class label','學習率是觀察到的類別標籤'],['Weights are the fixed filenames and never change','權重是固定檔名，永不改變'],['Learning rate and test accuracy are the same quantity','學習率和測試正確率是同一個量']],
'Learning rate is a training setting that influences the size of parameter changes; weights are parameters adjusted during learning. Neither the ground-truth label nor the evaluation accuracy is the learning rate. Filenames do not define model weights.','學習率是影響參數更新大小的訓練設定；權重是學習過程會調整的模型參數。真實標籤、評估正確率都不等於學習率，檔名也不是模型權重。');
add(25,'models','One project trains well with a particular learning rate. What should you conclude about using it on a different project?','某個學習率在一個專案訓練良好，對另一個專案應如何判斷？',[
['It is a candidate setting that still needs checking on the new problem','它是候選設定，仍須在新問題檢查'],['It is guaranteed optimal for every model and dataset','保證對每個模型與資料集都最佳'],['It guarantees recall of 100%','它保證召回率為 100%'],['It determines whether the target is binary or multiclass','它決定目標是二元或多類別']],
'Learning-rate behavior depends on the optimization problem and scale. A successful previous setting can inform a trial, but is not a universal guarantee. Recall and the target class structure are distinct from update size.','學習率的效果和最佳化問題及尺度有關，過往有效的設定可供嘗試，但不是通用保證。召回率與目標有幾種類別，也和更新步幅是不同概念。');
add(25,'models','After unstable training, someone proposes increasing the learning rate again because "larger always means faster learning." What is the best response?','訓練已不穩定，有人說「越大學越快」，建議再提高學習率，應如何回應？',[
['Larger steps can hurt convergence; inspect the loss behavior rather than assuming improvement','較大步幅可能妨礙收斂，應觀察損失而非假設一定改善'],['Agree, because update size cannot affect stability','同意，因為更新步幅不會影響穩定性'],['Replace every label with the learning-rate value','把所有標籤換成學習率數值'],['Judge training only by the color of its progress bar','只看進度條顏色判斷訓練']],
'Step size affects both speed and stability. When steps already overshoot, increasing them can worsen training. Label replacement corrupts the target and display colors provide no optimization evidence, so neither addresses the issue.','步幅同時影響速度與穩定性；若已越過低點，再放大可能更糟。替換標籤會破壞目標，介面顏色也不是最佳化證據，兩者都不能解決問題。');

add(84,'evaluation','For the same fixed cohort in the diagram, two missed positives become correctly detected, while FP stays fixed. What happens to recall and precision?','在圖中固定同一批案例，將兩個漏掉的陽性改為成功偵測，FP 維持不變。召回率與精確率如何變化？',[
['Both increase','兩者皆提高'],['Both decrease','兩者皆降低'],['Recall increases but precision must decrease','召回率提高，但精確率必定降低'],['Neither changes because the cohort size is unchanged','案例總數不變，所以兩者皆不變']],
'TP rises from 4 to 6 and FN falls from 6 to 4; actual positives remain 10, so recall rises. With FP fixed at 2, a larger share of positive predictions is correct, so precision also rises. A fixed cohort does not fix its metrics.','TP 從 4 變 6，FN 從 6 變 4，實際陽性仍為 10，所以召回率提高。FP 固定為 2 時，陽性預測中正確的比例也增加，所以精確率同時提高；案例總數固定不代表指標固定。',{tp:4,fp:2,fn:6,tn:8});
add(85,'evaluation','In the diagram\'s fixed cohort, three false alarms are corrected to true negatives, with TP and FN unchanged. Which metric changes?','在圖中固定案例，將三個誤報改正為真陰性，TP 與 FN 不變。哪個指標會改變？',[
['Precision improves while recall stays the same','精確率提高，召回率不變'],['Recall improves while precision stays the same','召回率提高，精確率不變'],['Both must become perfect','兩者必定都變成完美'],['Recall becomes zero','召回率變成零']],
'FP falls from 5 to 2, reducing incorrect positive predictions and increasing precision. Recall depends on TP and FN, which do not change. The remaining FN and FP mean neither metric has to be perfect or zero.','FP 從 5 變 2，錯誤陽性預測減少，精確率提高。召回率取決於 TP 和 FN，兩者未變；仍有 FN 和 FP，因此不能宣稱兩者都完美或召回率歸零。',{tp:6,fp:5,fn:2,tn:7});
add(85,'evaluation','If two true negatives in this fixed cohort are instead predicted positive, while all actual positives keep their predictions, what happens?','在圖中固定案例，兩個真陰性改被預測為陽性，所有實際陽性的預測不變。結果如何？',[
['Precision decreases and recall stays unchanged','精確率降低，召回率不變'],['Recall decreases but precision stays unchanged','召回率降低，精確率不變'],['Both metrics necessarily increase','兩者必定都提高'],['The task changes into regression','任務變成回歸']],
'Changing TN into FP adds false alarms without changing TP or FN. Precision falls because positive predictions include more mistakes; recall remains fixed. Changing prediction errors does not change a classification task into regression.','TN 變成 FP 增加誤報，但不改變 TP、FN。陽性預測含更多錯誤，使精確率降低；召回率維持不變。預測錯誤的改變不會把分類任務變成回歸。',{tp:8,fp:2,fn:2,tn:8});
add(84,'evaluation','Model A has the shown matrix. On the same cases, model B has the same TP and FN but fewer FP. Which comparison is valid?','模型 A 如圖，模型 B 在同一批案例的 TP、FN 相同，但 FP 較少。哪個比較成立？',[
['Their recalls match, but model B has better precision','召回率相同，但模型 B 精確率較佳'],['Their precisions must match, but B has better recall','精確率必定相同，但 B 召回率較佳'],['Fewer FP automatically implies more actual positives','FP 較少就表示實際陽性較多'],['No comparison is possible even with TP, FN and FP known','即使已知 TP、FN、FP 仍完全無法比較']],
'Matching TP and FN fixes recall. Fewer false positives with the same positive TP increases precision. Actual class membership is fixed for the same cases; a model does not create additional actual positives by changing predictions.','TP、FN 相同，召回率就相同；TP 為正且固定時，FP 較少會提高精確率。同一批案例的真實類別固定，模型改預測不會創造更多實際陽性。',{tp:6,fp:4,fn:4,tn:6});
add(89,'evaluation','Positive means "fragile parcel". In the diagram, which description matches the 4 items in FP?','正類定義為「易碎包裹」。圖中 FP 的 4 件代表什麼？',[
['Non-fragile parcels incorrectly flagged as fragile','非易碎包裹被誤判為易碎'],['Fragile parcels missed by the detector','真正易碎包裹未被抓到'],['Fragile parcels correctly flagged','真正易碎包裹被正確抓到'],['Non-fragile parcels correctly left unflagged','非易碎包裹被正確排除']],
'FP means predicted positive but actually negative. With fragile defined as positive, these are non-fragile items incorrectly flagged. Missed fragile items are FN; correct fragile flags are TP; correct non-fragile exclusions are TN.','FP 是預測為正類、實際為負類。此處正類為易碎，因此是非易碎品被誤報；漏掉的易碎品是 FN，正確抓到易碎品是 TP，正確排除非易碎品是 TN。',{tp:5,fp:4,fn:3,tn:8});
add(84,'evaluation','An all-negative classifier produces the shown matrix on 100 cases. It has 95% accuracy. What important failure does accuracy conceal?','全部預測負類的分類器，在 100 個案例得到圖中結果，準確率 95%。準確率掩蓋了什麼重要問題？',[
['It detects none of the five actual positives, so recall is zero','五個實際陽性全沒抓到，召回率為零'],['It has perfect recall because most examples are negative','因大多數案例為負類，所以召回率完美'],['It detected all five positives','它已抓到五個陽性'],['The matrix proves it is a regression model','矩陣證明它是回歸模型']],
'All five actual positives are FN and TP is zero. Accuracy is high only because 95 negatives were correctly excluded. It does not mean the positive class was detected. With no predicted positives, precision requires a zero-denominator convention, not an unsupported claim of perfect precision.','五個實際陽性全是 FN，TP 為零；準確率高只是因為 95 個負類被正確排除，不代表抓到了正類。由於沒有陽性預測，precision 的零分母須另按慣例處理，不能逕稱完美。',{tp:0,fp:0,fn:5,tn:95});
add(85,'evaluation','With the shown matrix, every actual positive is detected, but many negative cases trigger alarms. Which next goal directly addresses that problem while preserving current detections?','圖中所有實際陽性均被偵測，但許多負類也觸發警報。若保留現有成功偵測，哪個改善目標最直接？',[
['Reduce FP without increasing FN','減少 FP，並避免增加 FN'],['Reduce TP to zero','讓 TP 降為零'],['Convert correct detections into missed cases','把成功偵測改成漏掉'],['Rename recall as accuracy','把 recall 改名成 accuracy']],
'Recall is already perfect because FN is zero. False alarms are the FP problem, so reducing them while preserving TP and FN improves precision without losing recall. Destroying correct detections or renaming metrics does not address false alarms.','FN 為零，召回率已完美；誤報屬 FP 問題，若減少 FP 且維持 TP、FN，就能改善精確率而不犧牲召回率。刪除成功偵測或改指標名稱都無法解決誤報。',{tp:6,fp:9,fn:0,tn:5});
add(89,'evaluation','Positive means "a document is relevant". Which set of items should a reviewer examine to find relevant documents the system failed to retrieve?','正類代表文件相關。若要找出「相關但系統沒取回」的文件，應檢查圖中哪一格？',[
['FN, the 5 missed relevant documents','FN，5 份漏取的相關文件'],['FP, the 3 retrieved irrelevant documents','FP，3 份取回但不相關的文件'],['TN, the 7 excluded irrelevant documents','TN，7 份正確排除的不相關文件'],['TP, the 5 successfully retrieved relevant documents','TP，5 份成功取回的相關文件']],
'Relevant documents are actual positives. Failing to retrieve them is a negative prediction, hence FN. FP concerns unnecessary retrieval, while TN and TP are correct outcomes. Inspecting misses helps diagnose weak recall.','相關文件是實際正類，未取回是負類預測，因此屬 FN。FP 是多取了不相關文件，TN 與 TP 則是正確結果；檢視漏取項有助了解召回率不足的原因。',{tp:5,fp:3,fn:5,tn:7});
add(84,'evaluation','Using the matrix, a student says "recall is based on the 7 predicted positives." What should be corrected?','學生看圖後說「recall 是以 7 個預測陽性為基準」，應如何修正？',[
['Recall uses the 10 actual positives; 7 predicted positives is the basis for precision','Recall 以 10 個實際陽性為基準，7 個預測陽性是 precision 的基準'],['Recall must use only the 8 true negatives','Recall 必須只看 8 個真陰性'],['Recall ignores actual positive cases','Recall 不看實際陽性'],['Recall is always the total number of samples','Recall 永遠就是樣本總數']],
'The actual-positive row contains TP 4 plus FN 6, totaling 10. Predicted positives contain TP 4 plus FP 3, totaling 7. Confusing these groups swaps the meaning of recall and precision; true negatives do not form recall\'s reference group.','實際正類那一列為 TP 4 加 FN 6，共 10；預測正類為 TP 4 加 FP 3，共 7。混淆這兩組會顛倒召回率與精確率的意義，真陰性不是 recall 的參照族群。',{tp:4,fp:3,fn:6,tn:8});
add(85,'evaluation','A flagging system catches more actual positives after becoming more permissive, but also flags many more negatives. Which statement is justified?','偵測系統放寬判定後，抓到更多實際正類，也把更多負類列為正類。何者合理？',[
['Recall can improve while precision may worsen; both need checking','召回率可改善，但精確率可能變差，兩者都須檢查'],['More positive predictions always improve both metrics','預測更多正類一定同時改善兩者'],['Precision must improve whenever FP rises','FP 上升時 precision 必定提高'],['The true class labels must have changed','真實類別標籤一定改變']],
'Recovering missed positives improves recall on a fixed cohort. Extra false alarms can reduce the fraction of positive predictions that are correct, but the actual precision depends on the relative TP and FP changes. More alarms alone does not determine quality or change ground truth.','固定案例中少漏掉正類能提高召回率，但更多誤報可能降低陽性預測的正確比例；精確率實際如何，仍須看 TP、FP 的相對變化。警報變多本身不等於品質變好，也不會改變真實類別。');
add(84,'evaluation','Two systems have the same accuracy on the same imbalanced dataset. Can you conclude they miss the same number of actual positives?','兩個系統在同一個不平衡資料集上準確率相同，能否判定它們漏掉同樣多的實際陽性？',[
['No; the same total correct count can hide different TP and FN patterns','不能，正確總數相同仍可能有不同 TP、FN 分布'],['Yes; equal accuracy forces every confusion-matrix cell to match','可以，準確率相同就代表四格完全相同'],['Yes; accuracy and recall are synonyms','可以，accuracy 和 recall 同義'],['No; confusion matrices can only describe regression','不能，因混淆矩陣只能描述回歸']],
'Accuracy combines correct positive and correct negative decisions. Different allocations of those correct decisions can give the same accuracy but different recall and missed-positive counts. A confusion matrix helps expose this distinction in classification.','準確率把正確正類與正確負類一起計算，不同的正確數配置可能有相同準確率，卻有不同召回率及漏掉的正類數。混淆矩陣能呈現這種分類差異，而不是只適用於回歸。');
add(85,'evaluation','A classifier makes a positive prediction on only one case and gets it right, but misses many other actual positives. Which claim goes beyond the evidence?','分類器只對一筆案例預測正類且答對，卻漏掉許多其他實際正類。哪種說法超出證據？',[
['It is an excellent detector overall merely because its precision is perfect','只因精確率完美，就斷定它整體偵測能力極佳'],['Its one positive prediction was correct','它唯一一次正類預測正確'],['Missed actual positives lower recall','漏掉實際正類會降低召回率'],['Precision alone does not describe how many positives were missed','只看精確率無法描述漏掉多少正類']],
'A correct but very selective positive prediction can give perfect precision while recall remains poor. The observed one success is real, but does not establish strong overall detection. Both the amount of evidence and missed positives matter.','只做一次且正確的正類預測，可能有完美精確率，召回率卻很差。那一次成功確實存在，但不能據此認定整體偵測能力好，仍要看證據數量與漏掉的正類。');
add(85,'evaluation','On a fixed cohort, only correct negative predictions are converted into false alarms. Which group used to calculate recall is unchanged?','固定案例中，只有原本正確的負類預測被改成誤報。計算 recall 所用的哪組資料沒有改變？',[
['Actual positives and how many of them are detected','實際正類及其中成功偵測的數量'],['Predicted positives, which must remain unchanged','預測正類，必定完全不變'],['False positives, which must remain unchanged','FP，必定完全不變'],['Every cell of the matrix','矩陣每一格']],
'The altered cases are actual negatives, so TP and FN are unchanged. Recall is therefore unchanged even though predicted positives and FP increase. The matrix as a whole changes, so saying every cell remains fixed would be wrong.','變動的是實際負類，TP、FN 未變，因此 recall 不變；但預測正類與 FP 都會增加，不能說它們或矩陣每一格都維持不變。');
add(83,'evaluation','A report includes F1 in addition to precision and recall. What is F1 intended to summarize?','報告除了 precision、recall 也列 F1，F1 主要用來摘要什麼？',[
['A balance of precision and recall, rather than accuracy alone','Precision 與 recall 的綜合平衡，而不是單看準確率'],['The number of input feature columns','輸入特徵欄位數'],['The chosen learning rate','選定的學習率'],['The amount of missing data before cleaning','清理前缺值數量']],
'F1 combines precision and recall with a harmonic mean, so a very weak one limits the combined score. It is not a measure of feature count, step size, or missing values, and should still be interpreted in the application context.','F1 以調和平均綜合精確率與召回率，其中一項很弱會限制綜合分數。它不是特徵數、更新步幅或缺值量的指標，仍需依應用情境解讀。');
extra.at(-1).source.supplemental=true;extra.at(-1).source.url='https://scikit-learn.org/stable/modules/model_evaluation.html';
add(84,'evaluation','A report says "recall is high" but never defines which label is positive. What information is essential to interpret that statement?','報告只說「recall 很高」，卻未定義哪個標籤是正類。要解讀這句話，缺少什麼重要資訊？',[
['Which target class is being detected and treated as positive','被視為正類、要抓到的是哪個目標類別'],['The color of the chart background','圖表背景顏色'],['The exact spelling of the CSV filename','CSV 檔名的精確拼字'],['Whether the page uses a dark theme','頁面是否用深色主題']],
'Recall concerns detection of a specified actual-positive class. Without its identity, the reader cannot tell what the system successfully catches or misses. Styling and filenames do not identify the metric\'s target class.','Recall 關心的是某個指定實際正類有多少被抓到；若沒定義正類，讀者無法知道系統成功偵測或漏掉什麼。配色、檔名與主題不能取代目標類別定義。');

add(10,'preprocessing','In a Titanic survival exercise, a student places survived in both X and y. Which correction best matches the intended workflow?','Titanic 存活預測練習中，學生把 survived 同時放在 X 和 y，哪種修正最符合流程？',[
['Use survived as y and keep the outcome itself out of X','把 survived 作為 y，並從 X 排除目標結果本身'],['Use every label as an input and remove y','把所有結果當輸入並刪除 y'],['Replace survived with the filename','以檔名取代 survived'],['Ignore what X and y mean because the model can infer the task','不用管 X、y 的意義，模型會自己知道任務']],
'The workflow requires explicitly identifying features and the target. Feeding the exact outcome back as an input defeats the intended prediction task. A filename or a missing target definition cannot substitute for the observed survival label.','流程要求先明確區分特徵與目標；把要預測的結果直接當輸入，會破壞此預測任務的目的。檔名或省略目標定義，都不能取代觀察到的存活標籤。');
extra.at(-1).source.related=source(37).related||{file:'4. Preprocessing and Representation.pdf',locator:'p. 30',image:'./images/slides/lecture-4-p30.webp',note:'相關講義指定 survived 作為 y，其餘作為 X。'};
add(51,'preprocessing','Cities are coded 0, 1 and 2 even though no city is inherently "between" the others. Which concern should be raised before using these codes as quantities?','城市編碼為 0、1、2，但城市之間沒有內在的中間順序。把代碼當成量值使用前，應注意什麼？',[
['The codes may introduce an artificial order or distance between categories','代碼可能使類別帶入人為順序或距離'],['The codes prove that city names are continuous measurements','代碼證明城市名稱是連續量測值'],['The codes remove all missing data automatically','代碼會自動消除全部缺值'],['Every city must now be assigned all codes at once','每個城市必須同時取得全部代碼']],
'Arbitrary integer codes for nominal categories can be misinterpreted as ordered or spaced quantities by some models. Encoding does not create a real order or solve missing values. One-hot encoding is one way to represent separate nominal categories without that implied ranking.','名目類別的任意整數代碼，可能被某些模型當成有順序或距離的量。編碼不會創造真實順序，也不會自動處理缺值；one-hot 是避免暗示排名的一種表示方式。');
add(37,'preprocessing','A table has missing ages and missing embarkation ports. Which plan follows the Titanic classroom example?','資料表有缺少年齡和缺少登船港口，哪個方案符合 Titanic 課堂範例？',[
['Use a numeric mean for age and the most frequent category for port','年齡用數值平均，港口用最常出現類別'],['Average the spelling of port names','把港口名稱的拼字取平均'],['Replace every missing value with the target label','用目標標籤填所有缺值'],['Assume missing cells mean zero years and a port numbered zero','直接認定缺值是零歲和零號港口']],
'The classroom example fills age with a mean and embarked with a mode, respecting numeric versus categorical meaning. A mean of text names is undefined, target substitution leaks outcomes, and missing does not inherently mean zero. This is the example\'s plan, not a universal best rule for every dataset.','課堂範例對 age 用平均、embarked 用眾數，區分數值與類別意義。文字名稱不能直接取平均；拿結果填缺值會引入目標資訊；缺失也不等於零。這是範例方案，不是每個資料集都通用的最佳方法。');
add(52,'preprocessing','After filling missing embarkation-port values, three nominal ports remain. Which representation avoids assigning an artificial ranking?','填補登船港口缺值後，仍有三種名目港口，哪種表示避免加入人為排名？',[
['Three indicator features, one for each port','每個港口各一個指示特徵，共三個'],['A continuous price prediction as the new label','改用連續價格預測作為新標籤'],['A numeric code interpreted as a meaningful distance between ports','把數字代碼當成港口之間有意義的距離'],['Dropping y because encoding supplies the answer','因編碼已提供答案而刪除 y']],
'One-hot indicators represent membership in each category without claiming an ordinal relation. It is an input representation change, not a change to the target or a replacement for y. Treating arbitrary codes as genuine distances adds an unsupported relationship.','One-hot 指示欄表示各類別成員資格，不宣稱類別有大小順序。這是輸入表示的改變，不是改目標，也不取代 y；把任意代碼解讀成真實距離，會加入沒有依據的關係。');
add(42,'preprocessing','Age and fare use very different numeric scales, while port has already been one-hot encoded. Which operation matches the lecture\'s next step?','age、fare 的數值尺度差很多，港口已做 one-hot，哪個操作符合講義接續步驟？',[
['Apply min-max scaling to age and fare','對 age、fare 做 min-max 縮放'],['Treat each distinct age as a new target class','把每個不同年齡當新的目標類別'],['Average all column names','把所有欄位名稱取平均'],['Replace the survival target with the normalized age','用縮放後的年齡取代存活目標']],
'The Titanic exercise normalizes age and fare after encoding. Scaling addresses numeric ranges; it does not require changing the survival target or making every age a class. Averaging names has no numeric preprocessing meaning.','Titanic 練習在編碼後對 age、fare 正規化，目的是處理數值尺度，不是改變存活目標或把每個年齡都變成類別；欄位名稱取平均也沒有數值前處理意義。');
extra.at(-1).source.related={file:'4. Preprocessing and Representation.pdf',locator:'p. 36',image:'./images/slides/lecture-4-p36.webp',note:'講義此頁指定對 age、fare 做 Min-Max。'};
add(41,'preprocessing','Two hospital tables use different names for the same patient identifier and different units for the same measurement. What should integration address?','兩張資料表對同一病人識別欄使用不同名稱，相同量測又使用不同單位。整合時應處理什麼？',[
['Match corresponding entities and reconcile representations or units','對應相同實體，協調表示與單位差異'],['Assume different names always mean different patients','認定欄名不同就一定是不同病人'],['Concatenate values without checking their units','不查單位就直接串接數值'],['Choose an SVM kernel instead of checking the data','用選 SVM kernel 取代資料檢查']],
'Integration must identify shared entities and resolve value conflicts such as units or representations. Different field names do not prove different people, and concatenation without reconciliation can create inconsistencies. Model choice cannot repair an unchecked data join.','整合需辨認相同實體，並解決單位、表示等數值衝突。欄名不同不等於不同人，不經協調就串接可能造成不一致；選模型不能代替檢查資料對應。');
add(61,'representation','A single color image is stored as height × width × 3. What does the last axis normally represent in the lecture\'s RGB example?','單張彩色影像以高 × 寬 × 3 儲存，在講義的 RGB 範例中最後一軸代表什麼？',[
['The red, green and blue channels','紅、綠、藍三個通道'],['Three independent target class labels for every pixel','每個像素三個獨立目標類別'],['Three separate patients','三位不同病人'],['Three training/test splits','三種訓練測試切分']],
'The added axis encodes color channels for one image, not three images or labels. Height and width are spatial axes. A tensor shape describes storage dimensions; it does not by itself specify the number of target classes or dataset splits.','增加的軸表示同一張影像的色彩通道，不是三張影像或三種標籤；高與寬是空間軸。張量形狀描述儲存維度，本身不會決定目標類別數或訓練測試切分。');
add(63,'representation','Two documents are represented using the same bag-of-words vocabulary. For a word absent from one document but present in the vocabulary, what is its count feature?','兩份文件用同一詞袋字典表示，某字存在字典中，但沒有出現在其中一份文件，該詞頻特徵為何？',[
['Zero, while retaining that vocabulary dimension','為零，但保留該字典維度'],['Delete the dimension only for that document','只替該文件刪除該維度'],['Use its alphabetical position as its count','用字母排序位置當出現次數'],['Use the document\'s class label as the count','用文件類別標籤作為次數']],
'A shared vocabulary keeps feature positions aligned across documents. Absence means a zero count, not a different vector schema. Alphabetical position identifies a feature, not its frequency, and the target label must not be substituted into word counts.','共用字典讓各文件的特徵位置對齊，未出現就是次數為零，不應使向量架構隨文件改變。字母排序位置是特徵索引，不是詞頻；目標標籤也不能取代字詞出現次數。');
add(74,'representation','Two nonzero word-count vectors have the same proportions but very different lengths. Which comparison matches the lecture\'s reason for using cosine similarity?','兩個非零詞頻向量比例相同，但長度差很多，哪種比較符合講義使用餘弦相似度的理由？',[
['Compare their orientation so document length alone does not dominate','比較方向，避免只因文件長度主導結果'],['Treat the longer vector as automatically less relevant','直接認定較長向量一定較不相關'],['Use the filename length as the similarity','用檔名長度當相似度'],['Assume cosine ignores which words occur','認為餘弦完全不管出現哪些字']],
'Cosine focuses on orientation, so proportional vectors can be similar despite different magnitudes. It still depends on the feature values and vocabulary alignment; it does not use filenames or declare all long documents irrelevant.','餘弦著重方向，所以比例相同但量值不同的向量仍可相似。它仍取決於特徵值及字典對齊，並不是看檔名，也不是認定所有長文件都不相關。');
add(46,'representation','You have 100-dimensional feature vectors and want a two-dimensional scatter plot without changing the prediction target. Which role does PCA serve here?','已有 100 維特徵向量，想畫成二維散點圖，又不改變預測目標，PCA 在此的角色為何？',[
['Reduce the representation to a lower-dimensional view for visualization','將表示降至較低維度以供視覺化'],['Automatically create the true class labels','自動創造真實類別標籤'],['Guarantee all information and distances are perfectly preserved','保證全部資訊與距離完全保留'],['Replace model evaluation with a good-looking plot','用好看的圖取代模型評估']],
'PCA can project high-dimensional representations into two or three dimensions for viewing, as discussed in class. It does not manufacture labels, guarantee lossless preservation, or establish predictive quality from appearance alone.','課堂說明 PCA 可把高維表示投影到二或三維以便觀察，但它不會製造標籤、不保證資訊與距離完全無損，也不能只憑圖好看就認定預測品質良好。');

const short=[];
function essay(base,topic,en,zh,answerEn,answerZh,points,mistakeEn,mistakeZh,diagram){
  short.push({id:short.length+1,topic,en,zh,answer:{en:answerEn,zh:answerZh},keyPoints:points.map(([en,zh])=>({en,zh})),commonMistakes:{en:mistakeEn,zh:mistakeZh},source:source(base),...(diagram?{diagram:{type:'confusion',...diagram}}:{})});
}
essay(1,'foundations','Explain how to distinguish binary classification, multiclass classification and regression. Give one example of each.','說明如何區分二元分類、多類別分類與回歸，各舉一例。',
'Binary classification chooses between two categorical outcomes, such as spam or not spam. Single-label multiclass classification chooses one of more than two categories, such as positive, neutral or negative sentiment. Regression estimates a numeric amount, such as delivery time in minutes. The target meaning, not sample count or the appearance of digits, determines the task.','二元分類在兩種類別結果間選擇，例如垃圾或非垃圾郵件。單標籤多類別分類在超過兩類中選一類，例如正面、中立、負面情緒。回歸估計數值量，例如送達所需分鐘。判斷依目標意義，不是樣本數或是否寫成數字。',
[['Count possible categorical targets','辨認可選類別數'],['Distinguish categories from numeric quantities','區分類別和數值量'],['Give a matching example for each','各給一個符合定義的例子']],
'Do not call a problem regression just because category labels are encoded as integers.','不要因類別以整數編碼就把它稱為回歸。');
essay(2,'foundations','A text model must assign exactly one of happy, sad, angry or amused to each article. Explain the task type and why the single-label condition matters.','文字模型須替每篇文章指定開心、難過、生氣、有趣其中一類。說明任務類型，以及「只選一類」條件為何重要。',
'This is single-label multiclass classification because four possible categories exist and each article receives exactly one. If several emotions could be assigned simultaneously, that would require a different target design. The categories are not a continuous emotional score.','這是單標籤多類別分類，因有四種可能類別，每篇只得一種。如果允許同時給多種情緒，就需要不同的目標設計。這些類別也不是連續的情緒分數。',
[['Four possible categories','有四種可能類別'],['Exactly one output label per article','每篇恰好輸出一種標籤'],['Not a continuous numeric target','不是連續數值目標']],
'Having one assigned label does not make a task binary; binary means two possible classes.','只有一個被指派的標籤不等於二元分類；二元指的是有兩種可能類別。');
essay(10,'foundations','For a subscription-renewal prediction project, explain what X and y represent and why defining them should happen before model training.','以續訂預測專案說明 X、y 代表什麼，以及為何要在訓練前先定義。',
'X contains the input features, such as prior usage and subscription history. y is the observed renewal outcome the model should predict. Defining both clarifies the task, guides preprocessing, and prevents accidentally feeding the exact outcome into the inputs.','X 是輸入特徵，例如先前使用情形及訂閱紀錄；y 是模型要預測的已觀察續訂結果。先定義兩者能釐清任務、安排前處理，並避免把結果本身誤放進輸入。',
[['X is input information','X 是輸入資訊'],['y is the prediction target','y 是預測目標'],['Keep the outcome itself out of the inputs','不要把目標結果本身當作輸入']],
'Do not confuse the number of feature columns with the number of possible classes.','不要把特徵欄位數和可能類別數混為一談。');
essay(3,'foundations','A house-price project first predicts exact prices, then switches to low, medium or high price bands. Explain how and why the task type changes.','房價專案原本預測具體價格，後來改成低、中、高價位帶，說明任務類型如何改變及理由。',
'Predicting the exact price is regression because the target is a numeric quantity. Predicting one of three predefined price bands is single-label multiclass classification. The same input features can be used, but a different target changes what the model is trained to output.','預測具體價格是回歸，因目標為數值量；預測三種預設價位帶之一是單標籤多類別分類。即使沿用相同輸入特徵，目標改變仍會改變模型要學習的輸出。',
[['Exact price is a quantity','具體價格是數值量'],['Bands are discrete categories','價位帶是離散類別'],['Output definition determines task type','輸出定義決定任務類型']],
'The fact that price bands were formed from numbers does not make the band labels continuous predictions.','價位帶由數字劃分而來，不代表價位帶標籤本身就是連續數值預測。');
essay(21,'models','Explain the maximum-margin idea of a linear SVM using a simple separable two-class example.','用簡單線性可分的兩類範例說明線性 SVM 的最大間隔概念。',
'A linear SVM chooses a separating boundary between two classes. In a separable hard-margin example, it prefers the boundary with the widest minimum gap to the nearest class points. This is more specific than merely finding any line with zero training errors, and it does not guarantee perfect predictions on future data.','線性 SVM 選擇兩類之間的分隔邊界。在可分的硬間隔範例中，偏好距離最近類別點的最小間隔最寬的邊界，並非只找任意一條訓練零錯誤的線；這也不保證未來資料全部預測正確。',
[['Separating decision boundary','有分隔決策邊界'],['Maximize the minimum margin in the stated simple case','在指定簡化情況最大化最小間隔'],['Training separation is not a generalization guarantee','訓練可分不保證泛化完美']],
'The visible thickness of a plotted line is not the SVM margin.','圖上畫線的粗細不是 SVM 的間隔。');
essay(22,'models','What are support vectors, and why can they matter more directly than points far inside a class in a simple separable example?','什麼是支援向量？為何在簡單可分範例中，它們比深入類別內部的點更直接影響邊界？',
'Support vectors are training examples that constrain the SVM decision. In a simple hard-margin separable case, they are the points at the class margins nearest to the boundary. They limit how wide the separating margin can be, while moving a distant non-support point need not change the boundary if the constraints remain unchanged.','支援向量是對 SVM 決策構成限制的訓練樣本。在簡化的硬間隔可分情況，它們位於接近邊界的類別間隔上，限制可取得的分隔寬度；若限制不變，移動遠處的非支援點不一定改變邊界。',
[['They are training examples, not a separate class','它們是訓練樣本，不是額外類別'],['They constrain the separating solution','它們限制分隔解'],['State the separable hard-margin assumption','說明可分硬間隔的範例前提']],
'Do not claim that every point farthest from the boundary is a support vector.','不要說離邊界最遠的點就是支援向量。');
essay(23,'models','Explain what a kernel contributes to SVM and why a nonlinear kernel may help when a straight line fails in the original feature space.','說明 kernel 對 SVM 的作用，以及原特徵空間無法用直線分隔時，非線性 kernel 為何可能有幫助。',
'A kernel defines a way of comparing samples corresponding to a feature-space inner product. A nonlinear kernel can support a separating rule that appears nonlinear in the original space. It changes the model\'s representation of relationships, not the true class labels, and an appropriate choice still needs evaluation.','Kernel 定義對應特徵空間內積的樣本比較方式。非線性 kernel 可支援在原空間看來是非線性的分隔規則。它改變模型如何表示關係，不會改變真實類別標籤；選擇是否合適仍須評估。',
[['Kernel specifies feature-space comparison','Kernel 指定特徵空間的比較方式'],['Can enable nonlinear separation in the original space','可在原空間形成非線性分隔'],['No guarantee for every dataset','不保證適用所有資料集']],
'A kernel is not an instruction to discard labels or a promise of perfect test accuracy.','Kernel 不是刪除標籤的指令，也不是測試正確率完美的保證。');
essay(24,'models','Someone says "SVM has one main kernel that is always the right choice." Respond and describe a sensible way to choose between linear and nonlinear candidates.','有人說「SVM 有一種主要 kernel，而且永遠是正確選擇」。請回應，並說明如何合理比較線性與非線性候選。',
'SVM does not have one universally best kernel. A linear kernel can be suitable when a simple boundary fits the data, while a nonlinear candidate can model more complex relationships. Compare candidates using an appropriate evaluation procedure instead of equating software defaults or complexity with guaranteed quality.','SVM 沒有對所有問題都最佳的 kernel。當簡單邊界符合資料時，可考慮線性 kernel；非線性候選則可表達更複雜關係。應以合適評估程序比較，不能把軟體預設或複雜度當成品質保證。',
[['No universal best kernel','不存在通用最佳 kernel'],['Relate model complexity to data relationships','讓模型複雜度對應資料關係'],['Evaluate rather than rely on defaults','經過評估，而非只看預設值']],
'A library\'s default kernel is not a statement that the teacher or theory requires that kernel.','函式庫的預設 kernel 不等於老師或理論指定必須使用它。');
essay(25,'models','After a large increase in learning rate, training loss oscillates instead of settling. Explain a possible cause and a reasonable next check.','大幅提高學習率後，訓練損失持續震盪而不穩定。說明一個可能原因與合理的接續檢查。',
'The update steps may be too large, repeatedly overshooting a lower-loss region. Trying a smaller learning rate and comparing the loss behavior is a reasonable check. This observation does not prove that learning rate is the only possible cause, and a larger step is not always faster convergence.','更新步幅可能太大，反覆越過較低損失區域。可嘗試較小學習率，再比較損失變化；這不證明學習率是唯一可能原因，更大步幅也不一定更快收斂。',
[['Overshooting can cause oscillation','越過低點可能造成震盪'],['Compare behavior after a reasonable adjustment','合理調整後比較變化'],['Treat the diagnosis as a hypothesis','把診斷當成假設']],
'Do not claim that any oscillating curve conclusively proves one specific learning-rate value is wrong.','不要把任何震盪曲線都當成足以證明某個特定學習率必然錯誤。');
essay(26,'models','Why is choosing the smallest possible learning rate not automatically the best training strategy?','為何把學習率設成越小越好，不是自動最佳的訓練策略？',
'Learning rate controls the scale of parameter updates. Extremely small updates may make progress very slow, while excessively large updates can destabilize training. The goal is a suitable setting for the problem, based on observed training behavior, rather than simply minimizing or maximizing the learning rate.','學習率控制參數更新尺度。極小更新可能進展很慢，過大更新可能使訓練不穩定；應依問題與觀察到的訓練變化找合適設定，而不是單純追求最小或最大。',
[['Learning rate controls update size','學習率控制步幅'],['Too small may be slow; too large may be unstable','太小可能慢，太大可能不穩'],['Choose according to training behavior','依訓練變化選擇']],
'Learning rate is not the same as classification accuracy or the number of target classes.','學習率不等於分類正確率或目標類別數。');
essay(84,'evaluation','Using the matrix, explain precision and recall in words. Identify the reference group of each without a lengthy calculation.','依混淆矩陣用文字說明 precision 與 recall，指出兩者的參照族群，不需繁複計算。',
'Precision asks what fraction of predicted positives are truly positive, using TP and FP. Recall asks what fraction of actual positives are detected, using TP and FN. In this matrix the reference groups are 12 predicted positives and 10 actual positives; both metrics count the 8 true positives as successes.','Precision 問預測正類中有多少真的為正類，參照 TP 與 FP；recall 問實際正類中有多少被抓到，參照 TP 與 FN。圖中分別以 12 個預測正類及 10 個實際正類為基準，兩者都以 8 個 TP 作為成功數。',
[['Precision refers to predicted positives','Precision 參照預測正類'],['Recall refers to actual positives','Recall 參照實際正類'],['Both use TP as successes','兩者都以 TP 為成功數']],
'Do not swap FP and FN or use all four cells as recall\'s denominator.','不要顛倒 FP、FN，也不要把全部四格當 recall 的分母。',{tp:8,fp:4,fn:2,tn:6});
essay(89,'evaluation','Positive means a document is relevant. Explain the practical difference between a false positive and a false negative.','以文件相關為正類，說明 false positive 與 false negative 的實際差別。',
'A false positive is an irrelevant document that the system retrieves as relevant, creating unnecessary review. A false negative is a relevant document the system misses. False alarms reduce precision, while missed relevant documents reduce recall; the positive class must be defined before these terms are interpreted.','False positive 是不相關文件被當相關取回，增加無謂檢閱；false negative 是相關文件卻被漏掉。誤報會影響 precision，漏取會影響 recall；解讀前須先定義正類。',
[['FP is a false alarm','FP 是誤報'],['FN is a missed positive','FN 是漏掉正類'],['Connect each error to its interpretation','連結各種錯誤的實際意義']],
'Positive and negative refer to the designated class, not whether a document\'s wording sounds optimistic.','正負類是指定的目標類別，不是文件語氣樂觀與否。');
essay(84,'evaluation','A dataset contains 95 negatives and 5 positives. A model predicts everything negative. Explain why accuracy alone is misleading.','資料集有 95 個負類及 5 個正類，模型全部預測負類。說明只看準確率為何容易誤導。',
'The model gets the 95 negative cases right, so accuracy is 95%. However, TP is zero and all five positives are missed, giving recall zero. A high overall accuracy can therefore hide complete failure to detect a minority class, so the confusion matrix and task-relevant metrics should also be inspected.','模型答對 95 個負類，準確率為 95%；但 TP 為零，五個正類全漏掉，召回率為零。高整體準確率因此可能掩蓋對少數類別完全失敗，還應查看混淆矩陣及符合任務的指標。',
[['Majority-class success can dominate accuracy','多數類別成功可主導準確率'],['All actual positives are missed','實際正類全部漏掉'],['Use task-relevant evaluation beyond accuracy','除了準確率也看任務相關評估']],
'Do not call recall 95% or claim precision is perfect when there are no positive predictions.','不要說 recall 是 95%，也不要在沒有正類預測時宣稱 precision 完美。',{tp:0,fp:0,fn:5,tn:95});
essay(85,'evaluation','Two models detect the same 8 of 10 actual positives. Model A raises 2 false alarms and B raises 12. Compare their recall and precision.','兩模型都抓到 10 個實際正類中的 8 個；A 誤報 2 個，B 誤報 12 個。比較其 recall 與 precision。',
'Both models have the same recall because they detect the same number of the same actual positives. Model A has higher precision because it makes fewer false positive predictions for the same TP count. Choosing a model should also consider the application cost of misses and false alarms, rather than declaring one metric sufficient for all settings.','兩者對同一實際正類抓到的數量相同，因此 recall 相同。TP 固定而 A 的 FP 較少，所以 A 的 precision 較高。選模型仍要考量漏掉與誤報的應用代價，不能認為單一指標適用所有情境。',
[['Recall matches because TP and FN match','TP、FN 相同，所以 recall 相同'],['Fewer FP gives A higher precision','A 的 FP 較少，所以 precision 較高'],['Relate interpretation to the task','依任務解讀']],
'The total number of alarms does not equal the number of actual positive cases.','警報總數不等於實際正類總數。');
essay(90,'evaluation','An inspection task places high cost on missing a defective product, but false alarms also require manual work. Explain why both recall and precision should be reported.','檢驗任務很重視不要漏掉瑕疵品，但誤報也會增加人工工作。說明為何應同時報告 recall 與 precision。',
'Recall measures how many actual defective products are detected, so it describes the missed-defect concern. Precision measures how many flagged products are truly defective, reflecting unnecessary review from false alarms. Reporting both reveals the trade-off; flagging everything may avoid misses while burdening reviewers with many false alarms.','Recall 衡量真正瑕疵品有多少被抓到，對應漏檢問題；precision 衡量被標記產品中有多少真為瑕疵，反映誤報帶來的無謂檢閱。同時報告能看出取捨；全部都標記可能少漏檢，卻使人工承受大量誤報。',
[['Recall describes detection of actual defects','Recall 描述真正瑕疵的偵測'],['Precision describes reliability of alerts','Precision 描述警報可信度'],['Describe the cost trade-off','描述成本取捨']],
'A high recall does not by itself prove that false alarms are rare.','高 recall 本身不能證明誤報很少。');
essay(37,'preprocessing','Describe a basic preprocessing plan for Titanic age, fare and embarked, following the classroom example.','依課堂例子，描述 Titanic 的 age、fare、embarked 基本前處理方案。',
'First inspect the columns and missingness. In the classroom example, fill age and fare with their respective means and embarked with its mode. One-hot encode embarked, then apply the specified min-max scaling to age and fare. Keep survived as the target rather than an input feature.','先查看欄位與缺失情況。課堂範例以各自平均填 age、fare，以眾數填 embarked，再對 embarked 做 one-hot，並按指定對 age、fare 做 min-max。survived 保留作為目標，不是輸入特徵。',
[['Match imputation to column meaning','讓填補方法符合欄位意義'],['Encode the categorical input','編碼類別輸入'],['Scale numeric inputs and keep y separate','縮放數值輸入並區分 y']],
'The example\'s imputation choices are not universal best rules for every dataset.','範例的填補選擇不是每個資料集都適用的通用最佳規則。');
essay(51,'preprocessing','Compare label encoding and one-hot encoding for nominal arrival modes such as walk-in, ambulance and transfer.','以自行到院、救護車、轉院等名目到院方式，比較 label encoding 與 one-hot encoding。',
'Label encoding assigns a distinct integer to each category, but a model may interpret the codes as an order or distance that the categories do not possess. One-hot encoding uses a separate indicator for each category and avoids that artificial ranking. The representation should match whether an order is genuinely meaningful for the task.','Label encoding 為每種類別指定不同整數，但模型可能把代碼當成原類別沒有的順序或距離。One-hot 為每個類別建立獨立指示欄，避免暗示排名。表示方法應符合此任務是否真的有順序意義。',
[['Integer code versus indicator columns','整數代碼與指示欄的差異'],['Nominal categories have no inherent ranking','名目類別沒有內在排名'],['Encoding is not a change of target','編碼不是改變預測目標']],
'Do not assume code 2 is twice as much of a category as code 1.','不要認為代碼 2 代表某個類別是代碼 1 的兩倍。');
essay(42,'preprocessing','Why might age and fare be scaled before comparing feature vectors? Explain how standard min-max scaling differs conceptually from z-score standardization.','比較特徵向量前，為何可能要縮放 age、fare？概念上說明標準 min-max 與 z-score 的差異。',
'Different units and numeric ranges can make a larger-scale feature dominate a scale-sensitive comparison. Standard min-max maps the fitted nonconstant column into a chosen range, commonly zero to one. Z-score expresses values relative to the mean and standard deviation; it does not force every value into zero to one.','不同單位與數值範圍，可能讓較大尺度特徵主導對尺度敏感的比較。標準 min-max 將用來擬合的非固定值欄位映到指定範圍，常用零到一；z-score 則依平均與標準差表示相對位置，不會強制所有值都在零到一。',
[['Explain scale dominance','說明尺度主導問題'],['Min-max uses a target range','Min-max 使用目標範圍'],['Z-score is centered/scaled, not range-bounded','Z-score 是置中縮放，不保證範圍']],
'New values beyond the fitted min or max may fall outside the original min-max target range.','超出擬合時最小或最大值的新資料，轉換後可能超出原目標範圍。');
essay(74,'representation','Compare Manhattan distance, Euclidean distance and cosine similarity in words. Why can cosine be useful for documents with different lengths?','以文字比較曼哈頓距離、歐氏距離及餘弦相似度，並說明餘弦為何適合長度不同的文件。',
'Manhattan distance adds differences along coordinate directions, like following grid streets. Euclidean distance measures straight-line separation. Cosine similarity compares the orientation of nonzero vectors, so a change of overall length alone does not change it. This can help compare word-count proportions across documents of different lengths.','曼哈頓距離加總各座標方向差距，像沿格狀街道前進；歐氏距離量測直線間隔。餘弦相似度比較非零向量方向，因此只改變整體長度不會改變它，適合比較不同長度文件的詞頻比例。',
[['Street-route versus straight-line distance','街道路徑與直線距離的差別'],['Cosine compares orientation of nonzero vectors','餘弦比較非零向量方向'],['Connect magnitude invariance to document length','把尺度不變性連結到文件長度']],
'Cosine similarity still depends on which features are present; it does not ignore word identity.','餘弦仍取決於出現哪些特徵，不是完全忽略字詞身分。');
essay(46,'representation','Explain the role of PCA when visualizing high-dimensional representations, and state two things that a two-dimensional PCA plot cannot guarantee.','說明 PCA 在高維資料表示視覺化中的角色，並指出二維 PCA 圖不能保證的兩件事。',
'PCA can project high-dimensional feature vectors into a lower-dimensional view such as a two-dimensional plot. That view cannot guarantee that all original information or distances are preserved, and visually separated groups do not guarantee strong predictions on unseen data. PCA also does not automatically align independently trained language spaces.','PCA 可把高維特徵向量投影成低維視圖，例如二維散點圖。但不能保證保留全部原始資訊或距離；圖上看似分開的群組，也不保證對未見資料預測良好。PCA 亦不會自動對齊獨立訓練的語言空間。',
[['Dimensionality reduction for viewing','為觀察而降維'],['Projection can lose information','投影可能損失資訊'],['Appearance is not a predictive-performance guarantee','圖形外觀不保證預測表現']],
'Do not interpret a visualization algorithm as an automatic answer-label generator.','不要把視覺化演算法當成自動產生正確標籤的工具。');

if(extra.length!==50||short.length!==20)throw Error(`Unexpected counts: ${extra.length}/${short.length}`);
await writeFile('public/extra-questions.json',JSON.stringify(extra,null,2)+'\n');
await writeFile('public/short-questions.json',JSON.stringify(short,null,2)+'\n');
console.log('Created separate banks: 50 extra MCQs and 20 short-answer prompts. Original bank unchanged.');
